/// <summary>
/// Extension of form WMSArrivalOverview
/// </summary>
[ExtensionOf(formStr(WMSArrivalOverview))]
final class AVAWMSArrivalOverviewFrm_Extension
{
    public CreatedTransactionId avaCreatedTransactionId;

}

Method.Source:
/// <summary>
/// parm method for the createdTransactionId for ER print records (to delete correct records)
/// </summary>
/// <param name = "_createdTransactionId">CreatedTransactionId</param>
/// <returns>CreatedTransactionId</returns>
public CreatedTransactionId avaParmCreatedTransactionId(CreatedTransactionId _createdTransactionId = avaCreatedTransactionId)
{
    avaCreatedTransactionId = _createdTransactionId;

    return avaCreatedTransactionId;
}

/// <summary>
/// Extension of close method
/// </summary>
public void close()
{
    next close();

    this.avaDeletePrintRecords();
}

/// <summary>
/// starts the process of copying selected records
/// </summary>
public void avaCopySelectedRecords()
{
    ttsbegin;

    avaCreatedTransactionId = appl.curTransactionId(true);

    this.avaCopyOverviewRecords();
    this.avaCopyDetailRecords();

    ttscommit;
}

/// <summary>
/// Starts the process of deleting records not used in current print
/// </summary>
public void avaDeletePrintRecords()
{
    this.avaDeleteTransactionOverviewRecords();
    this.avaDeleteTransactionDetailRecords();
}

/// <summary>
/// Copies all selected Overview records to the TmpDB table AVAWMSArrivalOverviewTmp
/// </summary>
public void avaCopyOverviewRecords()
{
    AVAWMSArrivalOverviewTmp avaWMSArrivalOverviewTmp;
    WMSArrivalOverviewTmp wmsArrivalOverviewTmpLoc;
    RecordSortedList avaWMSArrivalOverview_recordList = new RecordSortedList(tableNum(AVAWMSArrivalOverviewTmp));

    avaWMSArrivalOverview_recordList.sortOrder(fieldNum(AVAWMSArrivalOverviewTmp, RecId));
    wmsArrivalOverviewTmpLoc = WMSArrivalOverviewTmp_ds.getFirst();

    while(wmsArrivalOverviewTmpLoc)
    {
        if(wmsArrivalOverviewTmpLoc.Selected == NoYes::Yes)
        {
            avaWMSArrivalOverviewTmp.clear();
            avaWMSArrivalOverviewTmp.initFromWMSArrivalOverview(wmsArrivalOverviewTmpLoc);
            avaWMSArrivalOverviewTmp.insert();

            avaWMSArrivalOverview_recordList.ins(avaWMSArrivalOverviewTmp);

        }

        wmsArrivalOverviewTmpLoc = WMSArrivalOverviewTmp_ds.getNext();
    }

    //avaWMSArrivalOverview_recordList.insertDatabase(); //it is inserted within user user connection so the framework will delete it automatically after the report is done.

}

/// <summary>
/// Copies all selected detail records to the TmpDB table AVAWMSArrivalDetailTmp
/// </summary>
public void avaCopyDetailRecords()
{
    AVAWMSArrivalDetailTmp avaWMSArrivalDetailTmp;
    WMSArrivalDetailTmp     wmsArrivalDetailTmpLoc;

    wmsArrivalDetailTmpLoc.setTmpData(wmsArrivalDetailTmp);

    while select wmsArrivalDetailTmpLoc
    {
        if(wmsArrivalDetailTmpLoc.Selected == NoYes::Yes)
        {
            avaWMSArrivalDetailTmp.clear();
            avaWMSArrivalDetailTmp.initFromWMSArrivalDetail(wmsArrivalDetailTmpLoc);
            avaWMSArrivalDetailTmp.insert();
        }
    }
}

/// <summary>
/// Deletes all records for specified transactionId
/// </summary>
public void avaDeleteTransactionOverviewRecords()
{
    AVAWMSArrivalOverviewTmp avaWMSArrivalOverviewTmp;

    ttsbegin;

    delete_from avaWMSArrivalOverviewTmp
        where (avaWMSArrivalOverviewTmp.CreatedTransactionId == avaCreatedTransactionId
            || avaWMSArrivalOverviewTmp.CreatedBy == curUserId());

    ttscommit;
}

/// <summary>
/// Deletes all records for specified transactionId
/// </summary>
public void avaDeleteTransactionDetailRecords()
{
    AVAWMSArrivalDetailTmp avaWMSArrivalDetailTmp;

    ttsbegin;

    delete_from avaWMSArrivalDetailTmp
        where (avaWMSArrivalDetailTmp.CreatedTransactionId == avaCreatedTransactionId
            || avaWMSArrivalDetailTmp.CreatedBy == curUserId());

    ttscommit;
}
